package com.company.platform.aigateway.orchestration;import java.util.*;import org.springframework.stereotype.Component;@Component public class ContextOrchestrator{public Map<String,Object> normalize(UUID tenantId,List<Map<String,Object>> sources){if(tenantId==null)throw new IllegalArgumentException("tenant required");Map<String,Object> result=new LinkedHashMap<>();result.put("tenantId",tenantId);Set<String> seen=new HashSet<>();for(Map<String,Object>s:sources==null?List.<Map<String,Object>>of():sources){Object key=s.getOrDefault("source",UUID.randomUUID().toString());if(seen.add(String.valueOf(key)))result.put(String.valueOf(key),Map.copyOf(s));}return result;}}
